 $isEdit=$incident!==null;$assignedVehicles=[];$assignedCrew=[];if($isEdit){$q=$db->prepare('SELECT vehicle_id FROM incident_vehicles WHERE incident_id=?');$q->execute([(int)$incident['id']]);$assignedVehicles=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));$q=$db->prepare('SELECT vehicle_id,personnel_id FROM incident_personnel WHERE incident_id=?');$q->execute([(int)$incident['id']]);foreach($q->fetchAll(PDO::FETCH_ASSOC) as $row)$assignedCrew[(int)$row['vehicle_id']][]=(int)$row['personnel_id'];}
 $diveraSuggested=[];$diveraResponses=[];if($isEdit){$q=$db->prepare('SELECT personnel_id FROM incident_divera_responses WHERE incident_id=? AND eligible=1');$q->execute([(int)$incident['id']]);$diveraSuggested=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));$q=$db->prepare('SELECT r.personnel_id,r.status_id,r.status_name,r.note,r.responded_at,r.eligible,p.name FROM incident_divera_responses r JOIN personnel p ON p.id=r.personnel_id WHERE r.incident_id=? ORDER BY r.eligible DESC,p.name');$q->execute([(int)$incident['id']]);$diveraResponses=$q->fetchAll(PDO::FETCH_ASSOC);}$diveraResponseHtml='';$diveraResponseTitle='👥 Divera-Rückmeldungen';if($diveraResponses){foreach($diveraResponses as $r){$rn=(string)$r['name'];$rs=trim((string)$r['status_name']);if($rs==='')$rs='Status '.(int)$r['status_id'];$rt=trim((string)$r['note']);$rid=(int)$r['personnel_id'];$diveraResponseHtml.='<label class="divera-response-row"><input type="checkbox" class="divera-response-person" value="'.$rid.'" '.($r['eligible']?'checked':'').' data-person-id="'.$rid.'"><span><strong>'.h($rn).'</strong><br><span class="muted">'.h($rs).($rt!==''?' · '.h($rt):'').'</span></span></label>';}}else{$diveraResponseTitle='👥 Keine Rückmeldung gefunden';foreach($people as $p){$rid=(int)$p['id'];$diveraResponseHtml.='<label class="divera-response-row"><input type="checkbox" class="divera-response-person" value="'.$rid.'" data-person-id="'.$rid.'"><span><strong>'.h($p['name']).'</strong><br><span class="muted">Keine DIVERA-Rückmeldung – manuell auswählbar</span></span></label>';}} $val=fn(string $key,string $default='')=>h($incident[$key]??$default);echo '<div class="card"><h1>'.($isEdit?'Einsatz bearbeiten':'Neuer Einsatz').'</h1><form method="post" enctype="multipart/form-data"><input type="hidden" name="form" value="incident">'.($isEdit?'<input type="hidden" name="incident_id" value="'.(int)$incident['id'].'">':'');echo '<label>Einsatznummer</label><input name="incident_number" value="'.$val('incident_number').'" placeholder="z. B. 2026-123"><label>Einsatz / Stichwort</label><input name="title" required value="'.$val('title').'" placeholder="z. B. Ölspur"><label>Einsatzort</label><input name="location" required value="'.$val('location').'" placeholder="z. B. Halchterstr. 2"><div class="time-grid"><div><label>Datum</label><input type="date" name="incident_date" value="'.$val('incident_date',date('Y-m-d')).'" required></div><div><label>Alarmierung</label><input type="time" name="alarm_time" value="'.$val('alarm_time').'" title="Zeitpunkt der Alarmierung"></div><div><label>Beginn <span class="muted">(Ende der kostenlosen gesetzlichen Hilfe)</span></label><input type="time" id="start_time" name="start_time" value="'.$val('start_time').'" title="Beginn des Einsatzes" oninput="updateDuration()"></div><div><label>Ende</label><input type="time" id="end_time" name="end_time" value="'.$val('end_time').'" title="Ende des Einsatzes" oninput="updateDuration()"></div><div class="duration-box"><label>Dauer</label><div id="duration_value" class="duration-value">–</div></div></div><div class="grid"><div><label>Einsatzleiter</label><input name="incident_leader" value="'.$val('incident_leader').'"></div><div><label>Dokument ausgefüllt von</label><input name="document_filled_by" value="'.$val('document_filled_by').'"></div></div><h2>Fahrzeuge und Besatzung</h2>';foreach($vehicles as $v){$vid=(int)$v['id'];$checked=in_array($vid,$assignedVehicles,true);echo '<div class="crew"><label class="check"><input type="checkbox" name="vehicles[]" value="'.$vid.'" '.($checked?'checked':'').' onchange="toggleVehicle(this)"> 🚒 '.h($v['name']).' <span class="muted">'.h($v['call_sign']).'</span></label><div class="actions"><a class="btn" href="#divera-response-modal" onclick="openDiveraResponseModal(this);return false;">👥 Gemeldete hier übernehmen</a></div><div class="crewlist" '.($checked?'':'hidden').'>';if(!$people)echo '<span class="muted">Noch kein Personal angelegt.</span>';foreach($people as $p){$pid=(int)$p['id'];$pc=in_array($pid,$assignedCrew[$vid]??[],true);echo '<label class="check person-choice '.(in_array($pid,$diveraSuggested,true)?'divera-suggested':'').'" data-person-id="'.$pid.'"><input type="checkbox" class="crew-person" name="crew['.$vid.'][]" value="'.$pid.'" '.($pc?'checked':'').' onchange="syncPersonSelection('.$pid.',this)"> '.h($p['name']).'</label>';}echo '</div></div>';}$val('material');echo '<label>Sonstiges Material (Freitext)</label><textarea name="material" rows="3">'.$val('material').'</textarea><label>Bemerkungen</label><textarea name="notes" rows="4">'.$val('notes').'</textarea><h2>Persondaten</h2><div class="grid person-grid">';foreach([['1','culprit1','Verursacher'],['2','culprit2','n/a'],['3','culprit_unknown','n/a']] as $p){$key=$p[1];$default=$p[2];$type=$incident[$key.'_type']??$default;echo '<div class="person-block '.($type==='n/a'?'person-na':'').'"><h3>Person '.$p[0].'</h3><label>Zuordnung</label><select name="'.$key.'_type" onchange="togglePersonData(this)"><option value="Verursacher"'.selectedType($type,'Verursacher').'>Verursacher</option><option value="Verursacher 2"'.selectedType($type,'Verursacher 2').'>Verursacher 2</option><option value="Unbekannt"'.selectedType($type,'Unbekannt').'>Unbekannt</option><option value="n/a"'.selectedType($type,'n/a').'>n/a</option></select><label>Name</label><input class="person-detail" name="'.$key.'_name" '.($type==='n/a'?'disabled':'').' value="'.$val($key.'_name').'"><label>Geburtsdatum</label><input class="person-detail" type="date" name="'.$key.'_birthdate" '.($type==='n/a'?'disabled':'').' value="'.$val($key.'_birthdate').'"><label>Adresse</label><textarea class="person-detail" name="'.$key.'_address" '.($type==='n/a'?'disabled':'').' rows="2">'.$val($key.'_address').'</textarea></div>'; }echo '</div><h2>📷 Einsatzbilder</h2><p class="muted">Bis zu 4 Bilder können mit diesem Einsatz verknüpft werden.</p><input type="file" name="incident_photos[]" accept="image/jpeg,image/png,image/webp" multiple><div class="photo-grid">'.implode('',array_map(fn($p)=>'<div class="photo-item"><img src="uploads/incidents/'.h($p['filename']).'" alt="Einsatzbild"></div>',$incidentPhotos)).'</div><div class="actions"><button type="submit">'.($isEdit?'Änderungen speichern':'Einsatz speichern').'</button></div></form><div id="divera-response-modal" class="divera-modal" hidden><div class="divera-modal-box"><div class="divera-modal-head"><h2>'.$diveraResponseTitle.'</h2><button type="button" class="danger" onclick="closeDiveraResponseModal()">✕</button></div><p class="muted">Wähle aus, welche gemeldeten Personen für dieses Fahrzeug übernommen werden sollen.</p><div class="divera-response-list">'.$diveraResponseHtml.'</div><div class="actions"><button type="button" onclick="applyDiveraResponses()">Auswahl übernehmen</button><button type="button" class="danger" onclick="closeDiveraResponseModal()">Abbrechen</button></div></div></div></div>';echo '<script>function updateDuration(){var s=document.getElementById("start_time"),e=document.getElementById("end_time"),d=document.getElementById("duration_value");if(!s||!e||!d)return;if(!s.value||!e.value){d.textContent="–";return;}var sp=s.value.split(":").map(Number),ep=e.value.split(":").map(Number),start=sp[0]*60+sp[1],end=ep[0]*60+ep[1];if(end<start)end+=1440;var minutes=end-start;d.textContent=Math.floor(minutes/60)+" Std. "+(minutes%60)+" Min.";}function syncPersonSelection(id,changed){document.querySelectorAll(".crew-person").forEach(function(cb){if(cb.value!==String(id))return;var label=cb.closest(".person-choice");if(changed===cb)return;cb.disabled=changed.checked;label.classList.toggle("disabled",changed.checked);});}function toggleVehicle(v){var crew=v.closest(".crew").querySelector(".crewlist");crew.hidden=!v.checked;}document.addEventListener("DOMContentLoaded",function(){updateDuration();document.querySelectorAll("select[name$=_type]").forEach(togglePersonData);var f=document.querySelector("input[name=\\\"incident_photos[]\\\"]");if(f)f.addEventListener("change",function(){if(this.files.length>4){alert("Maximal 4 Bilder erlaubt.");this.value="";}});});function togglePersonData(sel){var block=sel.closest(".person-block"),off=sel.value==="n/a";block.classList.toggle("person-na",off);block.querySelectorAll(".person-detail").forEach(function(el){el.disabled=off;});}function selectDiveraResponses(){document.querySelectorAll(".divera-suggested .crew-person").forEach(function(cb){cb.checked=true;cb.disabled=false;cb.closest(".person-choice").classList.remove("disabled");});}var activeDiveraCrew=null;function openDiveraResponseModal(btn){activeDiveraCrew=btn.closest(".crew");if(!activeDiveraCrew)return;document.querySelectorAll(".divera-response-person").forEach(function(cb){var target=activeDiveraCrew.querySelector(".crew-person[value=\""+cb.dataset.personId+"\"]");cb.checked=!!target&&target.checked;});var modal=document.getElementById("divera-response-modal");if(modal)modal.hidden=false;}function closeDiveraResponseModal(){document.getElementById("divera-response-modal").hidden=true;activeDiveraCrew=null;}function applyDiveraResponses(){if(!activeDiveraCrew)return;document.querySelectorAll(".divera-response-person").forEach(function(cb){var target=activeDiveraCrew.querySelector(".crew-person[value=\""+cb.dataset.personId+"\"]");if(!target)return;target.checked=cb.checked;target.disabled=false;target.closest(".person-choice").classList.remove("disabled");});closeDiveraResponseModal();}</script>';
}
